package io.github.abyxs.codingremote;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.net.Uri;
import android.os.ParcelFileDescriptor;
import android.util.Base64;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.concurrent.*;

/** Generated documents are isolated content, never application navigation or code. */
final class NativePreview {
    static void show(Activity activity,JSONObject value){
        NativeUi ui=new NativeUi(activity);Dialog dialog=new Dialog(activity,android.R.style.Theme_Material_Light_NoActionBar);LinearLayout root=new LinearLayout(activity);root.setOrientation(1);root.setBackgroundColor(NativeUi.CANVAS);root.setPadding(ui.dp(16),ui.dp(20),ui.dp(16),ui.dp(12));
        LinearLayout bar=new LinearLayout(activity);bar.setGravity(Gravity.CENTER_VERTICAL);TextView title=ui.text(value.optString("name","文件"),16,NativeUi.INK);title.setMaxLines(2);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button close=ui.iconButton("close","关闭预览");bar.addView(close,new LinearLayout.LayoutParams(ui.dp(48),ui.dp(48)));close.setOnClickListener(v->dialog.dismiss());root.addView(bar);FrameLayout content=new FrameLayout(activity);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));Button share=ui.button("保存或用其他应用打开",false);share.setEnabled(false);root.addView(share,new LinearLayout.LayoutParams(-1,ui.dp(48)));dialog.setContentView(root);dialog.getWindow().setWindowAnimations(activity.getResources().getIdentifier("DialogMotion","style",activity.getPackageName()));dialog.show();dialog.getWindow().setLayout(-1,-1);dialog.getWindow().setStatusBarColor(NativeUi.CANVAS);
        if(android.os.Build.VERSION.SDK_INT>=30){root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(ui.dp(16)+bars.left,Math.max(ui.dp(20),bars.top),ui.dp(16)+bars.right,Math.max(ui.dp(12),bars.bottom));return insets;});root.requestApplyInsets();}
        ExecutorService worker=Executors.newSingleThreadExecutor();final WebView[] web={null};final PdfRenderer[] pdf={null};final Bitmap[] bitmap={null};final boolean[] closed={false};
        // Decode and write off the UI thread; the provider exposes only this app's preview cache.
        worker.execute(()->{try{byte[] bytes=Base64.decode(value.getString("data"),Base64.DEFAULT);if(bytes.length>12*1024*1024)throw new IOException("文件超过预览大小限制");File dir=new File(activity.getCacheDir(),"previews");dir.mkdirs();File[] old=dir.listFiles();if(old!=null)for(File f:old)if(System.currentTimeMillis()-f.lastModified()>24*3600000L){File[] children=f.listFiles();if(children!=null)for(File child:children)if(child.isFile())child.delete();f.delete();}String name=value.optString("name","文件").replaceAll("[\\\\/:*?\"<>|]","_");File folder=new File(dir,java.util.UUID.randomUUID().toString());folder.mkdir();File file=new File(folder,name);try(OutputStream out=new FileOutputStream(file)){out.write(bytes);}String mime=value.optString("mime","application/octet-stream");
                activity.runOnUiThread(()->{if(closed[0]||activity.isFinishing())return;share.setEnabled(true);share.setOnClickListener(v->{Uri uri=Uri.parse("content://"+activity.getPackageName()+".previews/"+folder.getName()+"/"+Uri.encode(name));Intent intent=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(ClipData.newUri(activity.getContentResolver(),name,uri));activity.startActivity(Intent.createChooser(intent,"保存或打开文件"));});
                    if(mime.startsWith("image/")||mime.equals("text/html")){
                        WebView browser=new WebView(activity);web[0]=browser;WebSettings settings=browser.getSettings();settings.setJavaScriptEnabled(mime.equals("text/html"));settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setBlockNetworkLoads(true);settings.setBuiltInZoomControls(true);settings.setDisplayZoomControls(false);settings.setUseWideViewPort(true);settings.setLoadWithOverviewMode(true);browser.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest request){return true;}});content.addView(browser,new FrameLayout.LayoutParams(-1,-1));
                        String html=mime.startsWith("image/")?"<meta name='viewport' content='width=device-width, initial-scale=1'><body style='margin:0;background:#f6f7f2'><img style='width:100%;height:auto' src='data:"+mime+";base64,"+value.optString("data")+"'></body>":value.optString("text","");if(!html.toLowerCase(java.util.Locale.ROOT).contains("viewport"))html="<meta name='viewport' content='width=device-width, initial-scale=1'>"+html;browser.loadDataWithBaseURL("https://preview.invalid/",html,"text/html","UTF-8",null);
                    }else if(mime.equals("application/pdf")){
                        LinearLayout page=new LinearLayout(activity);page.setOrientation(1);ImageView image=new ImageView(activity);image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);page.addView(image,new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=new LinearLayout(activity);Button previous=ui.button("上一页",false),next=ui.button("下一页",false);TextView number=ui.text("",13,NativeUi.MUTED);number.setGravity(Gravity.CENTER);controls.addView(previous,new LinearLayout.LayoutParams(0,ui.dp(48),1));controls.addView(number,new LinearLayout.LayoutParams(0,ui.dp(48),1));controls.addView(next,new LinearLayout.LayoutParams(0,ui.dp(48),1));page.addView(controls);content.addView(page);final int[] index={0};final Runnable[] render={null};render[0]=()->{previous.setEnabled(false);next.setEnabled(false);worker.execute(()->{try{if(pdf[0]==null)pdf[0]=new PdfRenderer(ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY));int count=pdf[0].getPageCount();try(PdfRenderer.Page p=pdf[0].openPage(index[0])){float scale=Math.min(2,1600f/Math.max(p.getWidth(),p.getHeight()));Bitmap b=Bitmap.createBitmap(Math.max(1,(int)(p.getWidth()*scale)),Math.max(1,(int)(p.getHeight()*scale)),Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);activity.runOnUiThread(()->{if(closed[0]){b.recycle();return;}image.setImageBitmap(b);if(bitmap[0]!=null)bitmap[0].recycle();bitmap[0]=b;number.setText((index[0]+1)+" / "+count);previous.setEnabled(index[0]>0);next.setEnabled(index[0]+1<count);});}}catch(Exception e){activity.runOnUiThread(()->Toast.makeText(activity,"PDF 无法预览，可用其他应用打开",Toast.LENGTH_LONG).show());}});};previous.setOnClickListener(v->{index[0]--;render[0].run();});next.setOnClickListener(v->{index[0]++;render[0].run();});render[0].run();
                    }else if(value.has("text")){ScrollView scroll=new ScrollView(activity);LinearLayout body=new LinearLayout(activity);body.setOrientation(1);if(value.optBoolean("truncated"))body.addView(ui.text("预览已截断，完整内容请保存文件",12,NativeUi.MUTED));if(name.toLowerCase(java.util.Locale.ROOT).endsWith(".md")||mime.equals("text/markdown"))new MessageContent(activity,ui).render(body,value.optString("text"),false);else new MessageContent(activity,ui).code(body,value.optString("text"),name);scroll.addView(body);content.addView(scroll);}else content.addView(ui.text("此文件可保存，或使用已安装的应用打开。",15,NativeUi.MUTED));
                });
            }catch(Exception e){activity.runOnUiThread(()->{if(!closed[0])content.addView(ui.text("预览失败："+e.getMessage(),14,NativeUi.RED));});}});
        dialog.setOnDismissListener(d->{closed[0]=true;if(web[0]!=null)web[0].destroy();worker.execute(()->{if(pdf[0]!=null)pdf[0].close();});worker.shutdown();if(bitmap[0]!=null){bitmap[0].recycle();bitmap[0]=null;}});
    }
}
